// n8n Code node
// Mode: Run Once for All Items

const output = []

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i]

  // Read Markdown from the binary property produced by
  // "Read/Write Files from Disk"
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data')
  const markdown = buffer.toString('utf8')

  const lines = markdown.split(/\r?\n/)

  let currentCategory = null
  let insideTable = false

  for (const rawLine of lines) {
    const line = rawLine.trim()

    // Stop before the RAG notes at the end of the source file
    if (/^##\s+RAG ingestion notes/i.test(line)) {
      break
    }

    // Detect category headings: ## Cafés, ## Burgers + formules, etc.
    const headingMatch = line.match(/^##\s+(.+)$/)

    if (headingMatch) {
      currentCategory = headingMatch[1].trim()
      insideTable = false
      continue
    }

    // We only care about categories that contain item/price tables
    if (/^\|\s*Item\s*\|\s*Price\s*\(TND\)\s*\|/i.test(line)) {
      insideTable = true
      continue
    }

    // Skip markdown table separator
    if (insideTable && /^\|\s*:?-+\s*\|\s*:?-+\s*\|/.test(line)) {
      continue
    }

    // End table when line is no longer a table row
    if (insideTable && !line.startsWith('|')) {
      insideTable = false
      continue
    }

    if (!insideTable || !currentCategory) {
      continue
    }

    // Parse:
    // | Item Name | 12.500 |
    const rowMatch = line.match(/^\|\s*(.*?)\s*\|\s*([0-9]+(?:\.[0-9]+)?)\s*\|/)

    if (!rowMatch) {
      continue
    }

    const itemName = rowMatch[1].trim()
    const price = Number(rowMatch[2])

    if (!itemName || Number.isNaN(price)) {
      continue
    }

    output.push({
      json: {
        category: currentCategory,
        item_name: itemName,
        price_tnd: price,
        description: null,
        source_url:
          'https://fr.restaurantguru.com/Tarantino-cine-cafe-Monastir/menu',
        menu_photo_date: '2025-08-31',
        freshness_status: 'historical_menu_photo',
      },
    })
  }
}

return output
